import type { PuppyRepository } from '../../application';
import type { Puppy } from '../../domain';
import fixtures from './fixtures/puppies.json';

const all = fixtures as unknown as readonly Puppy[];

/** In-memory adapter over the committed fixtures (generated by scripts/build-fixtures.mjs). */
export class MockPuppyRepository implements PuppyRepository {
  async listAvailable(): Promise<readonly Puppy[]> {
    return all.filter((p) => p.status === 'available');
  }
  async listGoneHome(): Promise<readonly Puppy[]> {
    return all.filter((p) => p.status === 'gone-home');
  }
}
